const rail=document.querySelector('#timeRail'),detail=document.querySelector('#unitDetail'),filters=document.querySelector('#eraFilters');let currentUnits=[...GEO_UNITS],currentIndex=0;
const fmt=n=>n===0?'presente':`${Number.isInteger(n)?n:n.toFixed(3).replace(/0+$/,'').replace(/\.$/,'')} Ma`;
function renderRail(){rail.innerHTML='';let last='';currentUnits.forEach((u,i)=>{if(u.era!==last){const h=document.createElement('div');h.className='time-era-label';h.textContent=u.era;rail.appendChild(h);last=u.era}const b=document.createElement('button');b.type='button';b.className='time-unit';b.dataset.id=u.id;b.style.setProperty('--unit',u.color);b.innerHTML=`<i></i><span><small>${u.rank}</small><strong>${u.name}</strong></span><span>${fmt(u.start)}—${fmt(u.end)}</span>`;b.addEventListener('click',()=>selectUnit(i,true));rail.appendChild(b)});if(!currentUnits.length){rail.innerHTML='<p class="directory-empty">No hay unidades en este filtro.</p>';detail.innerHTML='';return}selectUnit(0,false)}
function selectUnit(index,updateHash){currentIndex=index;const u=currentUnits[index];rail.querySelectorAll('.time-unit').forEach(b=>b.classList.toggle('active',b.dataset.id===u.id));detail.style.setProperty('--unit',u.color);detail.innerHTML=`<p class="unit-rank">${u.era} · ${u.rank}</p><h2>${u.name}</h2><p class="unit-lead">${u.lead}</p><div class="unit-range"><div><span>COMIENZA</span><strong>${fmt(u.start)}</strong></div><div><span>TERMINA</span><strong>${fmt(u.end)}</strong></div><div><span>DURACIÓN APROX.</span><strong>${(u.start-u.end).toFixed(u.start-u.end<10?2:0)} Ma</strong></div></div><div class="subdivision-block"><h3>SUBDIVISIONES FORMALES / OPERATIVAS</h3><div>${(GEO_SUBDIVISIONS[u.id]||[]).map(x=>`<span>${x}</span>`).join('')}</div></div><div class="detail-grid"><section><h3>EL PLANETA</h3><p>${u.world}</p></section><section><h3>LA VIDA</h3><p>${u.life}</p></section><section><h3>LA EVIDENCIA</h3><p>${u.evidence}</p></section></div><div class="taxa-row">${u.taxa.map(t=>`<span>${t}</span>`).join('')}</div><p class="event-note">Punto de inflexión · ${u.event}</p><div class="unit-actions"><button id="prevUnit" ${index===0?'disabled':''}>← Anterior</button><button id="nextUnit" ${index===currentUnits.length-1?'disabled':''}>Siguiente →</button></div>`;detail.querySelector('#prevUnit').addEventListener('click',()=>selectUnit(Math.max(0,currentIndex-1),true));detail.querySelector('#nextUnit').addEventListener('click',()=>selectUnit(Math.min(currentUnits.length-1,currentIndex+1),true));if(updateHash)history.replaceState(null,'',`#${u.id}`)}
filters.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;filters.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));currentUnits=b.dataset.era==='Todos'?[...GEO_UNITS]:b.dataset.era==='Fanerozoico'?GEO_UNITS.filter(u=>u.era!=='Precámbrico'):GEO_UNITS.filter(u=>u.era===b.dataset.era);renderRail()});
renderRail();const requested=location.hash.slice(1);if(requested){const i=currentUnits.findIndex(u=>u.id===requested);if(i>=0)selectUnit(i,false)}
